def read(path,limit=4000000,keep=False):
 s=checked(path)
 if not stat.S_ISREG(s.st_mode) or s.st_size>limit:raise ValueError('File bound: '+str(path))
 fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
 try:
  before=os.fstat(fd)
